     1	// "All amounts are rounded to whole G in the MHPCO's favor" is one MHPCO
     2	// policy with two directions, because the MHPCO stands on opposite sides of
     3	// the two amounts: a premium is money owed to it, so a fraction is rounded up;
     4	// a payout is money owed by it, so a fraction is rounded down. Both directions
     5	// live here so the policy -- and the asymmetry that defines it -- has one home.
     6	export function amountOwedToMhpco(amount: number): number {
     7	  return Math.ceil(amount);
     8	}
     9	
    10	export function amountOwedByMhpco(amount: number): number {
    11	  return Math.floor(amount);
    12	}
