     1	import type { Item } from "./insured-item.js";
     2	import { amountOwedByMhpco } from "./mhpcos-favor.js";
     3	import { insuranceValue } from "./price-list.js";
     4	
     5	export interface Damage {
     6	  itemType: string;
     7	  amount: number;
     8	}
     9	
    10	export interface Incident {
    11	  cause: string;
    12	  damages: Damage[];
    13	}
    14	
    15	export interface Policy {
    16	  insuredItems: Item[];
    17	  // How much the MHPCO may still pay out over this policy's lifetime. This is
    18	  // the single figure the MHPCO tracks per policy: opening the policy sets it
    19	  // to the full cap, and each claim depletes it. The insurance sum it is
    20	  // derived from is never reported on its own.
    21	  remainingCap: number;
    22	}
    23	
    24	export interface ClaimResult {
    25	  payout: number;
    26	  remainingCap: number;
    27	  // The policy as it stands after this claim, for settling the next one.
    28	  policy: Policy;
    29	}
    30	
    31	const DEDUCTIBLE_PER_DAMAGE = 100;
    32	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    33	
    34	// The MHPCO insures a policy for the sum of its items' insurance values.
    35	function insuranceSum(insuredItems: Item[]): number {
    36	  return insuredItems
    37	    .map(insuranceValue)
    38	    .reduce((sum, value) => sum + value, 0);
    39	}
    40	
    41	// The MHPCO pays out at most twice the insurance sum over a policy's lifetime.
    42	// A policy is opened with that whole cap intact; each claim depletes it.
    43	export function openPolicy(insuredItems: Item[]): Policy {
    44	  return {
    45	    insuredItems,
    46	    remainingCap: insuranceSum(insuredItems) * CAP_MULTIPLE_OF_INSURANCE_SUM,
    47	  };
    48	}
    49	
    50	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    51	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    52	const FULL_REIMBURSEMENT_RATE = 1;
    53	
    54	// A damage entry names only the type of the item it befell, so the MHPCO can
    55	// identify the damaged item no further than the policy's first insured item of
    56	// that type. Where a policy covers several alike items this is a deliberate
    57	// approximation: alike items share the traits the reimbursement clauses read,
    58	// so any of them yields the same clause. Counting damage entries against the
    59	// insured items of their type -- and rejecting an excess -- is a separate rule
    60	// the MHPCO has not yet put into force.
    61	// The MHPCO settles a damage only against an item the policy actually covers.
    62	function firstInsuredItemOfType(policy: Policy, damage: Damage): Item {
    63	  const insured = policy.insuredItems.find(
    64	    (item) => item.type === damage.itemType,
    65	  );
    66	  if (insured === undefined) {
    67	    throw new Error(`the policy does not cover "${damage.itemType}"`);
    68	  }
    69	  return insured;
    70	}
    71	
    72	function isHighlyEnchanted(item: Item): boolean {
    73	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    74	}
    75	
    76	// Which reimbursement clause covers the damaged item. Damage to a highly
    77	// enchanted item is reimbursed at half; all other damage in full.
    78	// The dragon-material clause is subsumed by that default: it reimburses in
    79	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    80	// it never changes a payout and needs no branch of its own.
    81	// An item the policy does not list has no clause and is reimbursed in full --
    82	// rejecting such a damage entry is a separate, not yet implemented rule.
    83	function reimbursementRateFor(item: Item): number {
    84	  return isHighlyEnchanted(item)
    85	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    86	    : FULL_REIMBURSEMENT_RATE;
    87	}
    88	
    89	// The MHPCO settles each damage event separately: it reimburses the damage
    90	// under the applicable clause, then withholds its deductible once per event.
    91	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
    92	  const rate = reimbursementRateFor(firstInsuredItemOfType(policy, damage));
    93	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
    94	}
    95	
    96	// What the MHPCO owes for the whole incident before rounding: every damage
    97	// event settled under its clause, reduced to what the policy's lifetime cap
    98	// still allows.
    99	function cappedSettlement(policy: Policy, incident: Incident): number {
   100	  const settled = incident.damages
   101	    .map((damage) => settlementForDamageEvent(policy, damage))
   102	    .reduce((sum, amount) => sum + amount, 0);
   103	  return Math.min(settled, policy.remainingCap);
   104	}
   105	
   106	export function claim(policy: Policy, incident: Incident): ClaimResult {
   107	  // A payout is owed by the MHPCO, so its fraction is rounded down. Only this
   108	  // final amount is rounded; the settlement above stays fractional. Rounding
   109	  // last is safe for a capped claim too: the cap is always a whole number of
   110	  // G, so rounding a capped settlement changes nothing.
   111	  const payout = amountOwedByMhpco(cappedSettlement(policy, incident));
   112	  const remainingCap = policy.remainingCap - payout;
   113	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
   114	}
=== src/scenario.ts ===
     1	import { claim, openPolicy } from "./claim.js";
     2	import type { Incident, Policy } from "./claim.js";
     3	import type { Customer, Item } from "./insured-item.js";
     4	import { quote } from "./quote.js";
     5	
     6	export interface QuoteStep {
     7	  op: "quote";
     8	  items: Item[];
     9	}
    10	
    11	export interface ClaimStep {
    12	  op: "claim";
    13	  policy: number;
    14	  incident: Incident;
    15	}
    16	
    17	export type Step = QuoteStep | ClaimStep;
    18	
    19	export interface Scenario {
    20	  customer: Customer;
    21	  steps: Step[];
    22	}
    23	
    24	export interface QuoteResult {
    25	  premium: number;
    26	}
    27	
    28	export interface ClaimStepResult {
    29	  payout: number;
    30	  remainingCap: number;
    31	}
    32	
    33	export type StepResult = QuoteResult | ClaimStepResult;
    34	
    35	// The MHPCO settles a scenario's steps in order for a single customer: each
    36	// quote opens a policy the later claims draw on, and every quote after the
    37	// customer's first is a follow-up contract.
    38	export function runScenario(scenario: Scenario): StepResult[] {
    39	  const policies = new Map<number, Policy>();
    40	  let previousContracts = 0;
    41	  return scenario.steps.map((step, stepIndex) => {
    42	    if (step.op === "quote") {
    43	      const premium = quote(scenario.customer, step.items, previousContracts);
    44	      previousContracts += 1;
    45	      policies.set(stepIndex, openPolicy(step.items));
    46	      return { premium };
    47	    }
    48	    const result = claim(policyFor(policies, step.policy), step.incident);
    49	    policies.set(step.policy, result.policy);
    50	    return { payout: result.payout, remainingCap: result.remainingCap };
    51	  });
    52	}
    53	
    54	function policyFor(policies: Map<number, Policy>, stepIndex: number): Policy {
    55	  const policy = policies.get(stepIndex);
    56	  if (policy === undefined) {
    57	    throw new Error(`step ${stepIndex} did not create a policy`);
    58	  }
    59	  return policy;
    60	}
