     1	import { readFileSync } from "node:fs";
     2	import { runScenario } from "./scenario.js";
     3	import type { Scenario } from "./scenario.js";
     4	
     5	function readStdin(): string {
     6	  return readFileSync(0, "utf8");
     7	}
     8	
     9	// The MHPCO states why it refuses. Anything the office throws carries that
    10	// statement as its message; anything else that reaches the counter is passed
    11	// on as it stands.
    12	function refusalReason(reason: unknown): string {
    13	  return reason instanceof Error ? reason.message : String(reason);
    14	}
    15	
    16	// The MHPCO answers a scenario it accepts on stdout; one it refuses is
    17	// reported on stderr, and no results are written at all.
    18	try {
    19	  const scenario = JSON.parse(readStdin()) as Scenario;
    20	  const results = runScenario(scenario);
    21	  process.stdout.write(`${JSON.stringify({ results })}\n`);
    22	} catch (reason) {
    23	  process.stderr.write(`${refusalReason(reason)}\n`);
