import re
p = "src/claim.ts"
s = open(p).read()
old = '''// A damage entry names only the type of the item it befell, so the MHPCO can
// identify the damaged item no further than the policy's first insured item of
// that type. Where a policy covers several alike items this is a deliberate
// approximation: alike items share the traits the reimbursement clauses read,
// so any of them yields the same clause. Counting damage entries against the
// insured items of their type -- and rejecting an excess -- is a separate rule
// the MHPCO has not yet put into force.
// The MHPCO settles a damage only against an item the policy actually covers.
function firstInsuredItemOfType(policy: Policy, damage: Damage): Item {
  const insured = policy.insuredItems.find(
    (item) => item.type === damage.itemType,
  );
  if (insured === undefined) {
    throw new Error(`the policy does not cover "${damage.itemType}"`);
  }
  return insured;
}
'''
new = '''// Which of the policy's insured items a damage entry befell. A damage entry
// names only the type, so the MHPCO identifies the item no further than the
// policy's first insured item of that type. Where a policy covers several alike
// items this is a deliberate approximation: alike items share the traits the
// reimbursement clauses read, so any of them yields the same clause.
function insuredItemDamagedBy(policy: Policy, damage: Damage): Item | undefined {
  return policy.insuredItems.find((item) => item.type === damage.itemType);
}

// The MHPCO settles a damage only against an item the policy actually covers;
// a damage entry naming anything else is refused and the whole claim with it.
// Counting damage entries against the insured items of their type -- and
// refusing an excess -- is a further condition of coverage the MHPCO has not
// yet put into force.
function insuredItemCoveringDamage(policy: Policy, damage: Damage): Item {
  const insured = insuredItemDamagedBy(policy, damage);
  if (insured === undefined) {
    throw new Error(`the policy does not cover "${damage.itemType}"`);
  }
  return insured;
}
'''
assert old in s
s = s.replace(old, new).replace("reimbursementRateFor(firstInsuredItemOfType(policy, damage))", "reimbursementRateFor(insuredItemCoveringDamage(policy, damage))")
open(p, "w").write(s)
EOF
